"""Harness Intermediate Representation (IR).

Tool-agnostic. Composer produces an IR from layered templates; emitters consume it
and down-cast to the target tool's surface (Claude Code in v1; Codex/Copilot/Gemini/Cursor
in v2). Each spec mirrors the official Claude Code schema as documented in:

  - skills:  https://code.claude.com/docs/en/skills
  - agents:  https://code.claude.com/docs/en/sub-agents
  - rules:   https://code.claude.com/docs/en/memory#path-specific-rules
  - hooks:   https://code.claude.com/docs/en/hooks
  - plugins: https://code.claude.com/docs/en/plugins-reference
"""

from __future__ import annotations

from datetime import datetime
from typing import Any, Literal

from pydantic import BaseModel, ConfigDict, Field, field_validator

# ---- shared sub-models -----------------------------------------------------

ModelTier = Literal["opus", "sonnet", "haiku", "inherit"]
EffortLevel = Literal["low", "medium", "high", "xhigh", "max"]
Shell = Literal["bash", "powershell"]


class ProjectMetaIR(BaseModel):
    model_config = ConfigDict(extra="forbid")

    name: str
    description: str
    repo_root: str = "."


class MemoryDoc(BaseModel):
    """Rendered CLAUDE.md / AGENTS.md / .cursorrules content + scope."""

    model_config = ConfigDict(extra="forbid")

    scope: Literal["project", "user", "managed"] = "project"
    body: str


# ---- HookSpec --------------------------------------------------------------

HookEvent = Literal[
    "SessionStart", "Setup", "UserPromptSubmit", "UserPromptExpansion",
    "PreToolUse", "PermissionRequest", "PermissionDenied",
    "PostToolUse", "PostToolUseFailure", "PostToolBatch",
    "Stop", "StopFailure",
    "SubagentStart", "SubagentStop", "TeammateIdle",
    "TaskCreated", "TaskCompleted",
    "Notification",
    "InstructionsLoaded", "ConfigChange",
    "CwdChanged", "FileChanged",
    "PreCompact", "PostCompact",
    "Elicitation", "ElicitationResult",
    "WorktreeCreate", "WorktreeRemove",
    "SessionEnd",
]
HookHandlerType = Literal["command", "http", "mcp_tool", "prompt", "agent"]


class HookSpec(BaseModel):
    """Single hook entry. Lives in settings.json hooks, plugin hooks/hooks.json,
    or skill/agent frontmatter. Harness validates field combinations against handler type.
    """

    model_config = ConfigDict(extra="forbid", populate_by_name=True)

    event: HookEvent
    matcher: str | None = None
    if_: str | None = Field(default=None, alias="if")
    timeout: int | None = None
    status_message: str | None = Field(default=None, alias="statusMessage")
    once: bool = False

    type: HookHandlerType

    # type=command
    command: str | None = None
    shell: Shell = "bash"
    async_: bool = Field(default=False, alias="async")
    async_rewake: bool = Field(default=False, alias="asyncRewake")

    # type=http
    url: str | None = None
    headers: dict[str, str] | None = None
    allowed_env_vars: list[str] | None = Field(default=None, alias="allowedEnvVars")

    # type=mcp_tool
    server: str | None = None
    tool: str | None = None
    input: dict[str, Any] | None = None

    # type=prompt | agent
    prompt: str | None = None
    model: str | None = None  # not the same as ModelTier — accepts fully-qualified IDs


# ---- SkillSpec -------------------------------------------------------------

class SkillSpec(BaseModel):
    """Mirrors the official skill frontmatter spec field-for-field. Used both for
    knowledge skills and for slash commands (workflow skills with
    `disable_model_invocation=True`)."""

    model_config = ConfigDict(extra="forbid", populate_by_name=True)

    # frontmatter
    name: str | None = None
    description: str | None = None
    when_to_use: str | None = Field(default=None, alias="when_to_use")
    argument_hint: str | None = Field(default=None, alias="argument-hint")
    arguments: list[str] | None = None
    disable_model_invocation: bool = Field(default=False, alias="disable-model-invocation")
    user_invocable: bool = Field(default=True, alias="user-invocable")
    allowed_tools: list[str] | None = Field(default=None, alias="allowed-tools")
    model: str | None = None
    effort: EffortLevel | None = None
    context: Literal["fork"] | None = None
    agent: str | None = None
    hooks: list[HookSpec] | None = None
    paths: list[str] | None = None
    shell: Shell = "bash"

    # body + filesystem layout
    body: str
    relative_dir: str  # e.g. "skills/codebase-exploration" — used by emitter to write SKILL.md
    supporting_files: dict[str, str] = Field(default_factory=dict)  # filename -> content
    # True for skills the team owns (body filled by humans). On `harness generate`
    # we MUST NOT overwrite an existing file — preserving team-authored content
    # is the whole point of the scaffold-only policy. Set by the composer for
    # synthesised `<framework>-patterns` skills; off (default) for everything
    # Harness owns end-to-end (procedural skills, slash commands, etc.).
    preserve_on_regen: bool = False

    @field_validator("allowed_tools", "arguments", "paths", mode="before")
    @classmethod
    def _split_space_separated(cls, v):
        """Per official spec: accept space-separated string OR YAML list."""
        if isinstance(v, str):
            return [s for s in v.split() if s]
        return v


# ---- AgentSpec -------------------------------------------------------------

class AgentSpec(BaseModel):
    """Mirrors the official subagent frontmatter spec field-for-field. Body IS the
    system prompt — there is no `system_prompt` frontmatter key."""

    model_config = ConfigDict(extra="forbid", populate_by_name=True)

    # frontmatter
    name: str
    description: str
    tools: list[str] | None = None
    disallowed_tools: list[str] | None = Field(default=None, alias="disallowedTools")
    model: str | None = None
    permission_mode: Literal[
        "default", "acceptEdits", "auto", "dontAsk", "bypassPermissions", "plan"
    ] | None = Field(default=None, alias="permissionMode")
    max_turns: int | None = Field(default=None, alias="maxTurns")
    skills: list[str] | None = None  # CRITICAL: must list every skill the agent uses
    mcp_servers: list[str | dict[str, Any]] | None = Field(default=None, alias="mcpServers")
    hooks: list[HookSpec] | None = None
    memory: Literal["user", "project", "local"] | None = None
    background: bool = False
    effort: EffortLevel | None = None
    isolation: Literal["worktree"] | None = None
    color: Literal[
        "red", "blue", "green", "yellow", "purple", "orange", "pink", "cyan"
    ] | None = None
    initial_prompt: str | None = Field(default=None, alias="initialPrompt")

    # body
    body: str
    relative_path: str  # e.g. "agents/research-agent.md"

    @field_validator("tools", "disallowed_tools", "skills", mode="before")
    @classmethod
    def _split_space_separated(cls, v):
        if isinstance(v, str):
            return [s for s in v.split() if s]
        return v


# ---- RuleSpec --------------------------------------------------------------

class RuleSpec(BaseModel):
    """Path-specific rule. Frontmatter is paths-only per official spec (no name,
    description, or priority). File path is the rule identity."""

    model_config = ConfigDict(extra="forbid")

    relative_path: str  # e.g. "rules/frontend/nextjs-security.md"
    paths: list[str] | None = None  # absent = unconditional
    body: str


# ---- MCP & permissions -----------------------------------------------------

class MCPSpec(BaseModel):
    model_config = ConfigDict(extra="forbid")

    name: str
    transport: Literal["stdio", "sse", "http"] = "stdio"
    command: str | None = None
    args: list[str] | None = None
    url: str | None = None
    headers: dict[str, str] | None = None
    env: dict[str, str] | None = None  # values must be ${ENV} refs (lint F-007)
    scope: Literal["user", "project", "local"] = "project"


class PermissionSet(BaseModel):
    model_config = ConfigDict(extra="forbid")

    allow: list[str] = Field(default_factory=list)
    ask: list[str] = Field(default_factory=list)
    deny: list[str] = Field(default_factory=list)
    default_mode: Literal[
        "default", "acceptEdits", "plan", "auto", "dontAsk", "bypassPermissions"
    ] = Field(default="default", alias="defaultMode")


# ---- output styles & status line -------------------------------------------

class OutputStyleSpec(BaseModel):
    model_config = ConfigDict(extra="forbid")

    name: str
    description: str
    keep_coding_instructions: bool = False
    body: str
    relative_path: str  # e.g. "output-styles/Default.md"


class StatusLineSpec(BaseModel):
    model_config = ConfigDict(extra="forbid")

    command: str
    update_interval_ms: int = Field(default=500, alias="updateIntervalMs")


# ---- meta ------------------------------------------------------------------

class GenMeta(BaseModel):
    model_config = ConfigDict(extra="forbid")

    template_version: str
    harness_version: str
    generated_at: datetime
    source_layers: list[str]


# ---- top-level IR ----------------------------------------------------------

class HarnessIR(BaseModel):
    """Tool-agnostic harness representation. Composer produces; emitters consume."""

    model_config = ConfigDict(extra="forbid")

    project: ProjectMetaIR
    memory: list[MemoryDoc] = Field(default_factory=list)
    rules: list[RuleSpec] = Field(default_factory=list)
    skills: list[SkillSpec] = Field(default_factory=list)
    agents: list[AgentSpec] = Field(default_factory=list)
    hooks: list[HookSpec] = Field(default_factory=list)  # global hooks (settings.json)
    mcp_servers: list[MCPSpec] = Field(default_factory=list)
    # VS Code-style MCP `inputs` declarations (promptString etc.) carried through
    # from integration mcp fragments; emitted verbatim into .mcp.json when present.
    mcp_inputs: list[dict[str, Any]] = Field(default_factory=list)
    permissions: PermissionSet = Field(default_factory=PermissionSet)
    output_styles: list[OutputStyleSpec] = Field(default_factory=list)
    status_line: StatusLineSpec | None = None
    env_required: list[str] = Field(default_factory=list)
    metadata: GenMeta
